39	func newRecapCmd() *cobra.Command {
40		f := &recapFlags{view: string(recap.ViewBoth), agent: recap.AgentAll, color: recapColorAuto}
41		cmd := &cobra.Command{
42			Use:   "recap",
43			Short: "Summarize recent checkpoint activity",
44			RunE: func(cmd *cobra.Command, _ []string) error {
45				return runRecap(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), f)
46			},
47		}
48		cmd.Flags().BoolVar(&f.day, "day", false, "Today only (default)")
49		cmd.Flags().BoolVar(&f.week, "week", false, "Last 7 days")
50		cmd.Flags().BoolVar(&f.month, "month", false, "This calendar month")
51		cmd.Flags().BoolVar(&f.d90, "90", false, "Rolling 90 days")
52		cmd.Flags().StringVar(&f.agent, "agent", recap.AgentAll, "Agent id to show, or all")
53		cmd.Flags().StringVar(&f.view, "view", string(recap.ViewBoth), "Which columns to show: you, team, or both")
54		cmd.Flags().StringVar(&f.color, "color", recapColorAuto, "Color output: auto, always, or never")
55		cmd.Flags().BoolVar(&f.static, "static", false, "Print static output instead of opening the interactive recap")
56		cmd.Flags().BoolVar(&f.insecureHTTP, "insecure-http-auth", false, "Allow plain-HTTP auth (local dev only)")
57		cmd.MarkFlagsMutuallyExclusive("day", "week", "month", "90")
58		return cmd
59	}
