61	func (f *recapFlags) rangeKey() recap.RangeKey {
62		switch {
63		case f.week:
64			return recap.RangeWeek
65		case f.month:
66			return recap.RangeMonth
67		case f.d90:
68			return recap.Range90d
69		default:
70			return recap.RangeDay
