74	func (f *recapFlags) mode() recap.ViewMode {
75		switch strings.ToLower(strings.TrimSpace(f.view)) {
76		case "you", "me":
77			return recap.ViewYou
78		case "team", "contributors":
79			return recap.ViewTeam
80		case "both", "":
