95	func (f *recapFlags) colorEnabled(w io.Writer) (bool, error) {
96		switch strings.ToLower(strings.TrimSpace(f.color)) {
97		case "", recapColorAuto:
98			return shouldUseColor(w) && !IsAccessibleMode(), nil
99		case recapColorAlways:
100			return true, nil
101		case recapColorNever:
102			return false, nil
103		default:
104			return false, fmt.Errorf("invalid --color %q (use auto, always, or never)", f.color)
105		}
