112	func runRecap(ctx context.Context, w, errW io.Writer, f *recapFlags) error {
113		if _, err := paths.WorktreeRoot(ctx); err != nil {
114			fmt.Fprintln(errW, "Not a git repository. Run 'entire recap' from within a git repository.")
115			return NewSilentError(errors.New("not a git repository"))
116		}
117		mode := f.mode()
118		if !mode.Valid() {
119			return fmt.Errorf("invalid --view %q (use you, team, or both)", f.view)
120		}
121		color, err := f.colorEnabled(w)
122		if err != nil {
123			return err
124		}
125		client, err := NewAuthenticatedAPIClient(f.insecureHTTP)
126		if err != nil {
127			fmt.Fprintln(errW, "Sign in with `entire login` to use `entire recap`.")
128			return NewSilentError(err)
129		}
130		rangeKey := f.rangeKey()
131		repoSlug := currentRepoSlug(ctx)
132		if f.useTUI(interactive.IsTerminalWriter(w), interactive.CanPromptInteractively(), IsAccessibleMode()) {
133			return runRecapTUI(ctx, client, recapTUIOptions{
134				Range: rangeKey,
135				View:  mode,
136				Agent: f.agentName(),
137				Repo:  repoSlug,
138				Color: color,
139			})
140		}
141		start, end := rangeKey.Bounds(time.Now())
142		resp, err := recap.FetchMeRecap(ctx, client, start, end, repoSlug, 0)
143		if err != nil {
144			return handleRecapFetchError(errW, err)
145		}
146		fmt.Fprint(w, recap.RenderStaticRecap(resp, recap.RenderOptions{
147			Range: rangeKey,
148			View:  mode,
149			Agent: f.agentName(),
150			Width: terminalWidth(w),
151			Color: color,
152		}))
153		fmt.Fprintln(w)
154		return nil
155	}
156	
157	func handleRecapFetchError(w io.Writer, err error) error {
158		if shouldShowRecapLoadErrorMessage(err) {
159			fmt.Fprintln(w, recapLoadErrorMessage(err))
160			return NewSilentError(err)
161		}
162		return fmt.Errorf("fetch recap: %w", err)
163	}
164	
165	func shouldShowRecapLoadErrorMessage(err error) bool {
166		var apiErr *api.HTTPError
167		if errors.As(err, &apiErr) {
168			return apiErr.StatusCode == http.StatusUnauthorized ||
169				apiErr.StatusCode == http.StatusBadRequest ||
170				apiErr.StatusCode == http.StatusNotFound ||
171				apiErr.StatusCode >= http.StatusInternalServerError
172		}
173		return isRecapNetworkError(err)
174	}
175	
176	func terminalWidth(w io.Writer) int {
177		file, ok := w.(*os.File)
178		if !ok {
179			return recap.DefaultWidth
180		}
181		if !isatty.IsTerminal(file.Fd()) {
182			return recap.DefaultWidth
183		}
184		width, _, err := term.GetSize(int(file.Fd())) //nolint:gosec // fd values fit in int on supported platforms
185		if err != nil || width <= 0 {
186			return recap.DefaultWidth
187		}
188		return width
189	}
190	
191	func currentRepoSlug(ctx context.Context) string {
192		_, owner, repoName, err := gitremote.ResolveRemoteRepo(ctx, "origin")
193		if err != nil || owner == "" || repoName == "" {
194			return ""
195		}
196		return owner + "/" + repoName
197	}
