66	func newRecapTUIModel(ctx context.Context, client *api.Client, opts recapTUIOptions) recapTUIModel {
67		if opts.Range == "" {
68			opts.Range = recap.RangeDay
69		}
70		if opts.View == "" {
71			opts.View = recap.ViewBoth
72		}
73		if opts.Agent == "" {
74			opts.Agent = recap.AgentAll
