92	func (m recapTUIModel) Init() tea.Cmd {
93		return m.fetch(m.requestID)
94	}
95	
96	func (m recapTUIModel) fetch(requestID int) tea.Cmd {
97		return func() tea.Msg {
98			start, end := m.rangeKey.Bounds(time.Now())
99			resp, err := recap.FetchMeRecap(m.ctx, m.client, start, end, m.repo, 0)
100			if err != nil {
101				return recapErrMsg{requestID: requestID, err: err}
102			}
103			return recapDataMsg{requestID: requestID, resp: resp}
104		}
105	}
106	
107	func (m recapTUIModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
108		switch msg := msg.(type) {
109		case recapDataMsg:
110			if msg.requestID != m.requestID {
111				return m, nil
112			}
113			m.loading = false
114			m.loadErr = nil
115			m.resp = msg.resp
116			m = m.withViewport()
117			return m, nil
118	
119		case recapErrMsg:
120			if msg.requestID != m.requestID {
121				return m, nil
122			}
123			m.loading = false
124			m.loadErr = msg.err
125			return m, nil
126	
127		case tea.WindowSizeMsg:
128			if msg.Width > 0 {
129				m.width = msg.Width
130			}
131			m.height = max(msg.Height, 1)
132			m = m.withViewport()
133			return m, nil
134	
135		case tea.KeyPressMsg:
136			if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
137				return m, tea.Quit
138			}
139			switch msg.String() {
140			case "t":
141				m.rangeKey = nextRecapRange(m.rangeKey)
142				m.requestID++
143				m.loading = true
144				m.loadErr = nil
145				m.resp = nil
146				return m.withViewport(), m.fetch(m.requestID)
147			case "v":
148				m.view = nextRecapView(m.view)
149				return m.withViewport(), nil
150			case "a":
151				m.agent = m.nextAgent()
152				return m.withViewport(), nil
153			case "r":
154				m.requestID++
155				m.loading = true
156				m.loadErr = nil
157				return m, m.fetch(m.requestID)
158			}
159			if key.Matches(msg, keys.Home) {
160				m.viewport.GotoTop()
161				return m, nil
162			}
163			if key.Matches(msg, keys.End) {
164				m.viewport.GotoBottom()
165				return m, nil
166			}
167		}
168	
169		if m.ready {
170			var cmd tea.Cmd
171			m.viewport, cmd = m.viewport.Update(msg)
172			return m, cmd
173		}
174		return m, nil
175	}
176	
177	func (m recapTUIModel) View() tea.View {
178		v := tea.View{AltScreen: true}
179		if m.loadErr != nil {
180			v.SetContent(fmt.Sprintf("\n  Failed to load recap: %s\n\n  Press r to retry or q to quit.\n", recapLoadErrorMessage(m.loadErr)))
181			return v
182		}
183		if m.loading && m.resp == nil {
184			v.SetContent("\n  Loading recap...\n\n  Press q to quit.\n")
185			return v
186		}
187		if !m.ready {
188			return v
189		}
190	
191		var b strings.Builder
192		b.WriteString(m.viewport.View())
193		b.WriteString("\n")
194		b.WriteString(m.renderFooter())
195		v.SetContent(b.String())
196		return v
197	}
