199	func (m recapTUIModel) withViewport() recapTUIModel {
200		vpHeight := m.height - 1
201		if vpHeight < 1 {
202			vpHeight = 1
203		}
204		if !m.ready {
205			m.viewport = viewport.New(viewport.WithWidth(m.width), viewport.WithHeight(vpHeight))
206			m.ready = true
207		} else {
208			m.viewport.SetWidth(m.width)
209			m.viewport.SetHeight(vpHeight)
210		}
211		if m.resp != nil {
212			m.viewport.SetContent(recap.RenderStaticRecap(m.resp, recap.RenderOptions{
213				Range: m.rangeKey,
214				View:  m.view,
215				Agent: m.agent,
216				Width: m.width,
217				Color: m.color,
218			}))
219		}
220		return m
221	}
222	
223	func (m recapTUIModel) renderFooter() string {
224		choices := []string{
225			recapFooterLine(m.color, []recapHelpItem{
226				{"t", "range"},
227				{"v", "view"},
228				{"a", "agent"},
229				{"r", "refresh"},
230				{"↑/↓", "scroll"},
231				{"q", "quit"},
232			}),
233			recapFooterLine(m.color, []recapHelpItem{
234				{"t", "range"},
235				{"v", "view"},
236				{"a", "agent"},
237				{"q", "quit"},
238			}),
239			recapFooterLine(m.color, []recapHelpItem{
240				{"t", "range"},
241				{"v", "view"},
242				{"q", "quit"},
243			}),
244			recapFooterLine(m.color, []recapHelpItem{
245				{"q", "quit"},
246			}),
247		}
248		for _, choice := range choices {
249			if m.width <= 0 || lipgloss.Width(choice) <= m.width {
250				return choice
251			}
252		}
253		return ""
254	}
255	
256	type recapHelpItem struct {
257		key  string
258		desc string
259	}
260	
261	func recapFooterLine(color bool, items []recapHelpItem) string {
262		if !color {
263			parts := make([]string, 0, len(items))
264			for _, item := range items {
265				parts = append(parts, item.key+" "+item.desc)
266			}
267			return strings.Join(parts, " · ")
268		}
269		helpStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("241"))
270		keyStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Bold(true)
271		item := func(k, desc string) string {
272			return keyStyle.Render(k) + helpStyle.Render(" "+desc)
273		}
274		parts := make([]string, 0, len(items))
275		for _, helpItem := range items {
276			parts = append(parts, item(helpItem.key, helpItem.desc))
277		}
278		return strings.Join(parts, helpStyle.Render(" · "))
279	}
280	
281	func nextRecapRange(current recap.RangeKey) recap.RangeKey {
282		switch current {
283		case recap.RangeDay:
284			return recap.RangeWeek
285		case recap.RangeWeek:
286			return recap.RangeMonth
287		case recap.RangeMonth:
288			return recap.Range90d
289		case recap.Range90d:
290			return recap.RangeDay
291		default:
292			return recap.RangeDay
293		}
294	}
295	
296	func nextRecapView(current recap.ViewMode) recap.ViewMode {
297		switch current {
298		case recap.ViewBoth:
299			return recap.ViewYou
300		case recap.ViewYou:
301			return recap.ViewTeam
302		case recap.ViewTeam:
303			return recap.ViewBoth
304		default:
305			return recap.ViewBoth
306		}
307	}
308	
309	func (m recapTUIModel) nextAgent() string {
310		agents := m.agentIDs()
311		if len(agents) == 0 {
312			return recap.AgentAll
313		}
314		if m.agent == "" || m.agent == recap.AgentAll {
315			return agents[0]
316		}
317		for i, agentID := range agents {
318			if agentID == m.agent {
319				if i == len(agents)-1 {
320					return recap.AgentAll
321				}
322				return agents[i+1]
323			}
324		}
325		return recap.AgentAll
326	}
327	
328	func (m recapTUIModel) agentIDs() []string {
329		if m.resp == nil {
330			return nil
331		}
332		type agentItem struct {
333			id    string
334			label string
335		}
336		items := make([]agentItem, 0, len(m.resp.Agents))
337		for key, entry := range m.resp.Agents {
338			id := entry.AgentID
339			if id == "" {
340				id = key
341			}
342			if id == "" {
343				continue
344			}
345			label := entry.AgentLabel
346			if label == "" {
347				label = id
348			}
349			items = append(items, agentItem{id: id, label: label})
350		}
351		sort.SliceStable(items, func(i, j int) bool {
352			if items[i].label != items[j].label {
353				return items[i].label < items[j].label
354			}
355			return items[i].id < items[j].id
356		})
357		ids := make([]string, 0, len(items))
358		for _, item := range items {
359			ids = append(ids, item.id)
360		}
361		return ids
362	}
