// newRecapClient builds an API client for the recap commands without gating on
// a missing token. If a token exists in the keyring, it is attached to the
// client; otherwise the client is constructed with an empty bearer and the
// server's 401 response surfaces through FetchMeRecap → recapLoadErrorMessage,
// which produces the right "Run `entire login` to re-authenticate." message.
//
// This intentionally diverges from NewAuthenticatedAPIClient: it lets the
// command apply user-supplied flags (--week, --agent, --static, etc.) and run
// the same fetch path regardless of auth state, so flag effects and error
// messages are not collapsed into a single misleading "sign in" hint.
//
// The insecure-URL check is still enforced when a token is present (so we
// never send a bearer over plain HTTP without explicit opt-in via
// --insecure-http-auth).
func newRecapClient(insecureHTTP bool) (*api.Client, error) {
	token, _ := auth.LookupCurrentToken() //nolint:errcheck // keyring errors should not block the recap fetch; FetchMeRecap will surface 401 with the correct hint
	if token != "" && !insecureHTTP {
		if err := api.RequireSecureURL(api.BaseURL()); err != nil {
			return nil, fmt.Errorf("base URL check: %w", err)
		}
	}
	return api.NewClient(token), nil
}

